--
-- Tablo döküm verisi `expenses`
--


--
-- Tetikleyiciler `expenses`
--
DELIMITER $$
CREATE TRIGGER `after_expense_insert` AFTER INSERT ON `expenses` FOR EACH ROW BEGIN
    VALUES (
        NEW.created_by, 
        'INSERT', 
        'expenses', 
        NEW.id,
        NULL,
        CONCAT('New expense: ', NEW.amount, ' TL - ', NEW.description),
        '127.0.0.1',
        'System',
        NOW()
    );
END
$$
DELIMITER ;

