--
-- Görünüm yapısı `dashboard_summary`
--
DROP TABLE IF EXISTS `dashboard_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dashboard_summary`  AS SELECT (select count(0) from `apartment_units` where `apartment_units`.`status` = 1) AS `total_units`, (select sum(`dues`.`amount`) from `dues` where `dues`.`period_year` = year(curdate()) and `dues`.`period_month` = month(curdate())) AS `monthly_dues_total`, (select sum(`dues`.`amount`) from `dues` where `dues`.`period_year` = year(curdate()) and `dues`.`period_month` = month(curdate()) and `dues`.`is_paid` = 1) AS `monthly_dues_paid`, (select sum(`dues`.`amount`) from `dues` where `dues`.`period_year` = year(curdate()) and `dues`.`period_month` = month(curdate()) and `dues`.`is_paid` = 0) AS `monthly_dues_pending`, (select count(distinct `dues`.`unit_id`) from `dues` where `dues`.`is_paid` = 0 and `dues`.`due_date` < curdate()) AS `debt_units_count`, (select coalesce(sum(`incomes`.`amount`),0) from `incomes` where month(`incomes`.`income_date`) = month(curdate()) and year(`incomes`.`income_date`) = year(curdate())) AS `monthly_income`, (select coalesce(sum(`expenses`.`amount`),0) from `expenses` where month(`expenses`.`expense_date`) = month(curdate()) and year(`expenses`.`expense_date`) = year(curdate())) AS `monthly_expense` ;

-- --------------------------------------------------------

--
-- Görünüm yapısı `debt_status_view`
--
DROP TABLE IF EXISTS `debt_status_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `debt_status_view`  AS SELECT `au`.`id` AS `unit_id`, `a`.`name` AS `apartment_name`, `au`.`unit_number` AS `unit_number`, `au`.`floor` AS `floor`, `au`.`resident_name` AS `resident_name`, `au`.`owner_name` AS `owner_name`, `au`.`resident_phone` AS `resident_phone`, `au`.`resident_email` AS `resident_email`, coalesce(sum(`d`.`amount`),0) AS `total_dues`, coalesce(sum(case when `d`.`is_paid` = 1 then `d`.`amount` else 0 end),0) AS `total_paid`, coalesce(sum(case when `d`.`is_paid` = 0 then `d`.`amount` else 0 end),0) AS `total_debt`, count(case when `d`.`is_paid` = 0 and `d`.`due_date` < curdate() then 1 end) AS `overdue_count`, max(`p`.`payment_date`) AS `last_payment_date`, CASE WHEN coalesce(sum(case when `d`.`is_paid` = 0 then `d`.`amount` else 0 end),0) = 0 THEN 'Güncel' WHEN count(case when `d`.`is_paid` = 0 AND `d`.`due_date` < curdate() then 1 end) <= 1 THEN 'Gecikmiş' ELSE 'Kritik' END AS `debt_status` FROM (((`apartment_units` `au` left join `apartments` `a` on(`au`.`apartment_id` = `a`.`id`)) left join `dues` `d` on(`au`.`id` = `d`.`unit_id`)) left join `payments` `p` on(`d`.`id` = `p`.`due_id`)) GROUP BY `au`.`id`, `a`.`name`, `au`.`unit_number`, `au`.`floor`, `au`.`resident_name`, `au`.`owner_name`, `au`.`resident_phone`, `au`.`resident_email` ;

-- --------------------------------------------------------

--
-- Görünüm yapısı `dues_payment_history`
--
DROP TABLE IF EXISTS `dues_payment_history`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dues_payment_history`  AS SELECT `d`.`id` AS `id`, `a`.`name` AS `apartment_name`, `au`.`unit_number` AS `unit_number`, `au`.`resident_name` AS `resident_name`, `dd`.`name` AS `due_type`, `d`.`amount` AS `due_amount`, `d`.`period_year` AS `period_year`, `d`.`period_month` AS `period_month`, `d`.`due_date` AS `due_date`, `d`.`is_paid` AS `is_paid`, `d`.`payment_date` AS `payment_date`, coalesce(`p`.`amount`,0) AS `paid_amount`, `p`.`payment_method` AS `payment_method`, `p`.`receipt_number` AS `receipt_number`, CASE WHEN `d`.`is_paid` = 1 THEN 'Ödendi' WHEN `d`.`due_date` < curdate() THEN 'Gecikmiş' ELSE 'Bekliyor' END AS `payment_status` FROM ((((`dues` `d` join `apartment_units` `au` on(`d`.`unit_id` = `au`.`id`)) join `apartments` `a` on(`d`.`apartment_id` = `a`.`id`)) join `dues_definitions` `dd` on(`d`.`due_definition_id` = `dd`.`id`)) left join `payments` `p` on(`d`.`id` = `p`.`due_id`)) ORDER BY `d`.`due_date` DESC, `au`.`unit_number` ASC ;

-- --------------------------------------------------------

--
-- Görünüm yapısı `financial_report_summary`
--
DROP TABLE IF EXISTS `financial_report_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `financial_report_summary`  AS SELECT `financial_report_view`.`report_year` AS `report_year`, `financial_report_view`.`report_month` AS `report_month`, 'Toplam Rapor' AS `report_type`, sum(`financial_report_view`.`total_income`) AS `total_income`, sum(`financial_report_view`.`dues_income`) AS `dues_income`, sum(`financial_report_view`.`rent_income`) AS `rent_income`, sum(`financial_report_view`.`other_income`) AS `other_income`, sum(`financial_report_view`.`total_expenses`) AS `total_expenses`, sum(`financial_report_view`.`electric_expense`) AS `electric_expense`, sum(`financial_report_view`.`water_expense`) AS `water_expense`, sum(`financial_report_view`.`gas_expense`) AS `gas_expense`, sum(`financial_report_view`.`cleaning_expense`) AS `cleaning_expense`, sum(`financial_report_view`.`security_expense`) AS `security_expense`, sum(`financial_report_view`.`maintenance_expense`) AS `maintenance_expense`, sum(`financial_report_view`.`repair_expense`) AS `repair_expense`, sum(`financial_report_view`.`door_expense`) AS `door_expense`, sum(`financial_report_view`.`insurance_expense`) AS `insurance_expense`, sum(`financial_report_view`.`tax_expense`) AS `tax_expense`, sum(`financial_report_view`.`other_expenses`) AS `other_expenses`, sum(`financial_report_view`.`net_profit`) AS `net_profit`, CASE WHEN sum(`financial_report_view`.`total_income`) > 0 THEN round(sum(`financial_report_view`.`total_expenses`) / sum(`financial_report_view`.`total_income`) * 100,2) ELSE 0 END AS `expense_ratio`, CASE WHEN sum(`financial_report_view`.`total_income`) > sum(`financial_report_view`.`total_expenses`) THEN 'Kar' WHEN sum(`financial_report_view`.`total_income`) < sum(`financial_report_view`.`total_expenses`) THEN 'Zarar' ELSE 'Başabaş' END AS `profit_status` FROM `financial_report_view` GROUP BY `financial_report_view`.`report_year`, `financial_report_view`.`report_month` ORDER BY `financial_report_view`.`report_year` DESC, `financial_report_view`.`report_month` DESC ;

-- --------------------------------------------------------

--
-- Görünüm yapısı `financial_report_view`
--
DROP TABLE IF EXISTS `financial_report_view`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `financial_report_view`  AS SELECT `combined_data`.`report_year` AS `report_year`, `combined_data`.`report_month` AS `report_month`, 'Aylık Rapor' AS `report_type`, sum(`combined_data`.`total_income`) AS `total_income`, sum(`combined_data`.`dues_income`) AS `dues_income`, sum(`combined_data`.`rent_income`) AS `rent_income`, sum(`combined_data`.`other_income`) AS `other_income`, sum(`combined_data`.`total_expenses`) AS `total_expenses`, sum(`combined_data`.`electric_expense`) AS `electric_expense`, sum(`combined_data`.`water_expense`) AS `water_expense`, sum(`combined_data`.`gas_expense`) AS `gas_expense`, sum(`combined_data`.`cleaning_expense`) AS `cleaning_expense`, sum(`combined_data`.`security_expense`) AS `security_expense`, sum(`combined_data`.`maintenance_expense`) AS `maintenance_expense`, sum(`combined_data`.`repair_expense`) AS `repair_expense`, sum(`combined_data`.`door_expense`) AS `door_expense`, sum(`combined_data`.`insurance_expense`) AS `insurance_expense`, sum(`combined_data`.`tax_expense`) AS `tax_expense`, sum(`combined_data`.`other_expenses`) AS `other_expenses`, sum(`combined_data`.`total_income`) - sum(`combined_data`.`total_expenses`) AS `net_profit`, CASE WHEN sum(`combined_data`.`total_income`) > 0 THEN round(sum(`combined_data`.`total_expenses`) / sum(`combined_data`.`total_income`) * 100,2) ELSE 0 END AS `expense_ratio`, CASE WHEN sum(`combined_data`.`total_income`) > sum(`combined_data`.`total_expenses`) THEN 'Kar' WHEN sum(`combined_data`.`total_income`) < sum(`combined_data`.`total_expenses`) THEN 'Zarar' ELSE 'Başabaş' END AS `profit_status` FROM (select year(`incomes`.`income_date`) AS `report_year`,month(`incomes`.`income_date`) AS `report_month`,sum(`incomes`.`amount`) AS `total_income`,sum(case when `incomes`.`category_id` = 1 then `incomes`.`amount` else 0 end) AS `dues_income`,sum(case when `incomes`.`category_id` = 2 then `incomes`.`amount` else 0 end